INSERT INTO `user_assessment` (`id`, `assessment_id`, `notes`, `status`, `Percentage`, `user_id`, `is_submitted`, `level`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES
	(1, 11, '<p style="box-sizing: border-box; line-height: 28px; font-family: Poppins, Helvetica, sans-serif; margin-top: 4px !important; margin-bottom: 0px !important; color: #a1a5b7 !important;">Level One Information</p>\r\n<p style="box-sizing: border-box; line-height: 28px; font-family: Poppins, Helvetica, sans-serif; margin-top: 4px !important; margin-bottom: 0px !important; color: #a1a5b7 !important;">This competency is about property and asset inspection, fundamental to providing accurate advice on machinery and business assets or property. It is important that candidates are able to demonstrate knowledge and understanding of the core requirements of property and asset inspection. Assessors will be seeking confirmation that all candidates have good knowledge of building construction, location analysis and defects..Level One Information</p>\r\n<p style="box-sizing: border-box; line-height: 28px; font-family: Poppins, Helvetica, sans-serif; margin-top: 4px !important; margin-bottom: 0px !important; color: #a1a5b7 !important;">This competency is about property and asset inspection, fundamental to providing accurate advice on machinery and business assets or property. It is important that candidates are able to demonstrate knowledge and understanding of the core requirements of property and asset inspection. Assessors will be seeking confirmation that all candidates have good knowledge of building construction, location analysis and defects..Level One Information</p>\r\n<p style="box-sizing: border-box; line-height: 28px; font-family: Poppins, Helvetica, sans-serif; margin-top: 4px !important; margin-bottom: 0px !important; color: #a1a5b7 !important;">This competency is about property and asset inspection, fundamental to providing accurate advice on machinery and business assets or property. It is important that candidates are able to demonstrate knowledge and understanding of the core requirements of property and asset inspection. Assessors will be seeking confirm